"use client";

import { type HTMLAttributes, type KeyboardEvent, type ReactNode, useMemo, useState } from "react";
import { cx } from "../utils/cx";
import { ChevronRightIcon } from "../icons/interface";

export type TreeNode = {
  id: string;
  label: ReactNode;
  children?: TreeNode[];
  disabled?: boolean;
  /** Leading icon. */
  icon?: ReactNode;
};

export type TreeProps = Omit<HTMLAttributes<HTMLUListElement>, "onSelect" | "children"> & {
  "aria-label": string;
  nodes: TreeNode[];
  selected?: string | null;
  defaultSelected?: string | null;
  /** Called with the new selection when it changes (not when the selected node is chosen again). */
  onSelectedChange?: (id: string) => void;
  expanded?: string[];
  defaultExpanded?: string[];
  onExpandedChange?: (ids: string[]) => void;
};

type Flat = { node: TreeNode; level: number; parent: string | null; pos: number; size: number };

function flatten(
  nodes: TreeNode[],
  open: Set<string>,
  level = 1,
  parent: string | null = null,
  out: Flat[] = [],
): Flat[] {
  nodes.forEach((node, i) => {
    out.push({ node, level, parent, pos: i + 1, size: nodes.length });
    if (node.children?.length && open.has(node.id)) flatten(node.children, open, level + 1, node.id, out);
  });
  return out;
}

/**
 * A hierarchy (folders, galleries within clients). ARIA tree with one tab stop: Up and Down move, Right opens or
 * steps into a branch, Left closes or steps out, Home and End jump, Enter or Space selects. Branches open with an
 * animated height.
 */
export function Tree({
  nodes,
  selected: controlledSelected,
  defaultSelected = null,
  onSelectedChange,
  expanded: controlledExpanded,
  defaultExpanded = [],
  onExpandedChange,
  className,
  onKeyDown,
  ...rest
}: TreeProps) {
  const [innerSel, setInnerSel] = useState<string | null>(defaultSelected);
  const selected = controlledSelected === undefined ? innerSel : controlledSelected;
  const [innerOpen, setInnerOpen] = useState<string[]>(defaultExpanded);
  const openIds = controlledExpanded ?? innerOpen;
  const open = useMemo(() => new Set(openIds), [openIds]);
  const visible = useMemo(() => flatten(nodes, open), [nodes, open]);
  const [focusId, setFocusId] = useState<string | null>(null);
  const current =
    focusId && visible.some((v) => v.node.id === focusId) ? focusId : (selected ?? visible[0]?.node.id ?? null);

  const setOpen = (id: string, next: boolean) => {
    const ids = next ? [...openIds, id] : openIds.filter((x) => x !== id);
    if (controlledExpanded === undefined) setInnerOpen(ids);
    onExpandedChange?.(ids);
  };
  const choose = (id: string) => {
    if (id === selected) return;
    if (controlledSelected === undefined) setInnerSel(id);
    onSelectedChange?.(id);
  };
  const focus = (id: string | undefined, root: HTMLElement) => {
    if (!id) return;
    setFocusId(id);
    root.querySelector<HTMLElement>(`[data-tree-id="${CSS.escape(id)}"]`)?.focus();
  };

  const key = (e: KeyboardEvent<HTMLUListElement>) => {
    onKeyDown?.(e);
    if (e.defaultPrevented) return;
    const i = visible.findIndex((v) => v.node.id === current);
    const here = visible[i];
    if (!here) return;
    const root = e.currentTarget;
    const hasKids = !!here.node.children?.length;
    const isOpen = open.has(here.node.id);
    const next = (from: number, dir: 1 | -1) => {
      for (let n = from + dir; n >= 0 && n < visible.length; n += dir)
        if (!visible[n]?.node.disabled) return visible[n]?.node.id;
    };
    if (e.key === "ArrowDown") focus(next(i, 1), root);
    else if (e.key === "ArrowUp") focus(next(i, -1), root);
    else if (e.key === "Home") focus(visible.find((v) => !v.node.disabled)?.node.id, root);
    else if (e.key === "End") focus([...visible].reverse().find((v) => !v.node.disabled)?.node.id, root);
    else if (e.key === "ArrowRight") {
      if (hasKids && !isOpen) setOpen(here.node.id, true);
      else if (hasKids) focus(visible[i + 1]?.node.id, root);
    } else if (e.key === "ArrowLeft") {
      if (hasKids && isOpen) setOpen(here.node.id, false);
      else if (here.parent) focus(here.parent, root);
    } else if (e.key === "Enter" || e.key === " ") {
      if (here.node.disabled) return;
      choose(here.node.id);
      if (hasKids) setOpen(here.node.id, !isOpen);
    } else return;
    e.preventDefault();
  };

  const renderList = (list: TreeNode[], level: number): ReactNode =>
    list.map((node, idx) => {
      const kids = node.children?.length ? node.children : null;
      const isOpen = !!kids && open.has(node.id);
      return (
        // biome-ignore lint/a11y/useValidAriaRole: "none" is a valid role (the li is only structure)
        <li key={node.id} role="none" className="hm-tree-node">
          {/* biome-ignore lint/a11y/useKeyWithClickEvents: keys are handled on the tree */}
          <div
            role="treeitem"
            tabIndex={node.id === current ? 0 : -1}
            data-tree-id={node.id}
            aria-level={level}
            aria-posinset={idx + 1}
            aria-setsize={list.length}
            aria-expanded={kids ? isOpen : undefined}
            aria-selected={selected === node.id}
            aria-disabled={node.disabled || undefined}
            className="hm-tree-item"
            style={{ "--_level": level - 1 } as React.CSSProperties}
            onFocus={() => setFocusId(node.id)}
            onClick={() => {
              if (node.disabled) return;
              choose(node.id);
              if (kids) setOpen(node.id, !isOpen);
            }}
          >
            <ChevronRightIcon
              className="hm-tree-chevron"
              data-leaf={kids ? undefined : ""}
              size={12}
              strokeWidth={1.6}
            />
            {node.icon ? <span className="hm-tree-icon">{node.icon}</span> : null}
            <span className="hm-tree-label">{node.label}</span>
          </div>
          {kids ? (
            <div
              className="hm-collapsible-content hm-tree-children"
              data-state={isOpen ? "open" : "closed"}
              inert={isOpen ? undefined : true}
            >
              <ul role="group" className="hm-collapsible-inner hm-tree-group">
                {renderList(kids, level + 1)}
              </ul>
            </div>
          ) : null}
        </li>
      );
    });

  return (
    <ul {...rest} role="tree" className={cx("hm-tree", className)} onKeyDown={key}>
      {renderList(nodes, 1)}
    </ul>
  );
}
